/**
 * Independent QA: lib/scene.py export contract, checked against Blender itself.
 *
 * Scenes are generated by fixtures/gen_scenes.py, exported with lib/scene.py
 * exactly as the Host runs it, and every claim is compared with answers from
 * fixtures/oracle.py running inside Blender on the original .blend.
 */
import { after, before, describe, it } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { SKIP_NO_BLENDER, oracle, pool, prepareCorpus, removeDir, sha256 } from "./helpers/blender.mjs";
import { centroid, meshInstances, readGlb, toZup, trianglesOf } from "./helpers/glb.mjs";
import { loadResolver } from "./helpers/blocks.mjs";

const SCENES = ["xform", "mods", "bools", "special", "empty", "multiscene", "huge", "library"];
const NOAPPLY = ["mods", "bools"];

describe("scene.py export contract (Blender ground truth)", { skip: SKIP_NO_BLENDER }, () => {
  let corpus;
  const glbs = {};
  const facts = {};
  const evalAnswers = {};

  before(async () => {
    corpus = await prepareCorpus("export", SCENES, NOAPPLY);
    for (const [name, ex] of Object.entries(corpus.exports)) if (ex.code === 0) glbs[name] = readGlb(ex.glbPath);
    // Ask Blender which evaluated polygon (and therefore which source face/mesh) lies under every triangle.
    await pool(Object.keys(glbs), 4, async (name) => {
      const queries = [];
      for (const inst of meshInstances(glbs[name])) {
        trianglesOf(glbs[name], inst).forEach((tri, k) => {
          if (!tri.faceIds) return;
          queries.push({ id: `${inst.nodeIndex}:${k}`, object: inst.name, local: toZup(centroid(tri.localGl)) });
        });
      }
      const skipEval = name === "library"; // duplicate object names make a by-name query ambiguous
      const answer = await oracle(corpus.blends[name], skipEval ? {} : { evalface: queries }, corpus.dir);
      facts[name] = answer;
      evalAnswers[name] = new Map((answer.evalface || []).map((a) => [a.id, a]));
    });
  });
  after(() => removeDir(corpus?.dir));

  it("every export exits 0 and writes both artifacts", () => {
    for (const ex of [...Object.values(corpus.exports), ...Object.values(corpus.noapply)]) {
      assert.equal(ex.code, 0, `${ex.glbPath}\n${ex.stderr.slice(-2000)}`);
      assert.ok(existsSync(ex.glbPath) && statSync(ex.glbPath).size > 0, ex.glbPath);
      assert.ok(ex.info && ex.info.annotate, `${ex.jsonPath} has annotate`);
      assert.match(ex.stdout, /BLEND_PREVIEW_OK/);
    }
  });

  it("never modifies the .blend (sha256/size/mtime) nor its linked library, and leaves no stray files", () => {
    for (const ex of [...Object.values(corpus.exports), ...Object.values(corpus.noapply)]) {
      assert.deepEqual(ex.after, ex.before, `blend changed by export: ${ex.glbPath}`);
    }
    const now = readdirSync(corpus.sceneDir).sort();
    assert.deepEqual(now, Object.keys(corpus.filesBefore).sort(), "no .blend1/.part files next to the scenes");
    for (const [file, before] of Object.entries(corpus.filesBefore)) {
      const path = join(corpus.sceneDir, file);
      assert.equal(sha256(path), before.hash, `${file} bytes changed`);
      assert.equal(statSync(path).mtimeMs, before.mtimeMs, `${file} mtime changed`);
    }
    const leftovers = readdirSync(corpus.outDir).filter((f) => f.includes(".part"));
    assert.deepEqual(leftovers, [], "no *.part artifacts left behind");
  });

  it("every exported triangle carries exactly one integer faceId and one srcId", () => {
    const problems = [];
    for (const [name, glb] of Object.entries(glbs)) {
      for (const inst of meshInstances(glb)) {
        for (const tri of trianglesOf(glb, inst)) {
          if (!tri.faceIds) continue;
          const ids = [...tri.faceIds, ...tri.srcIds, ...tri.vertIds];
          if (!ids.every((v) => Number.isInteger(v))) problems.push(`${name}/${inst.name}: non-integer id ${ids}`);
          if (new Set(tri.faceIds).size !== 1) problems.push(`${name}/${inst.name}: faceIds ${tri.faceIds}`);
          if (new Set(tri.srcIds).size !== 1) problems.push(`${name}/${inst.name}: srcIds ${tri.srcIds}`);
        }
      }
    }
    assert.deepEqual(problems.slice(0, 20), []);
  });

  it("GLB faceId/srcId equal the face and mesh Blender's own modifier evaluation puts under each triangle", () => {
    const mismatches = [];
    let checked = 0;
    for (const [name, glb] of Object.entries(glbs)) {
      if (name === "library") continue;
      const meshes = corpus.exports[name].info.annotate.meshes;
      for (const inst of meshInstances(glb)) {
        if (inst.name === "Reimported") continue; // covered by its own test below
        if (inst.name === "ShapeKeyed") continue; // GLB keeps the basis + a morph target; see viewer-pick.test.js
        trianglesOf(glb, inst).forEach((tri, k) => {
          if (!tri.faceIds) return;
          const truth = evalAnswers[name].get(`${inst.nodeIndex}:${k}`);
          checked += 1;
          const gotMesh = meshes[tri.srcIds[0] - 1]?.name ?? `out-of-range srcId ${tri.srcIds[0]}`;
          // Non-planar evaluated polygons (bevel corners) triangulate differently in the BVH, so allow a small gap.
          if (truth.dist > 1e-2) mismatches.push(`${name}/${inst.name}#${k}: centroid ${truth.dist} off Blender's evaluated surface`);
          else if (truth.qa_face !== tri.faceIds[0] - 1 || truth.qa_mesh !== gotMesh) {
            mismatches.push(`${name}/${inst.name}#${k}: GLB face ${tri.faceIds[0] - 1} of ${gotMesh}, Blender face ${truth.qa_face} of ${truth.qa_mesh}`);
          }
        });
      }
    }
    assert.ok(checked > 800, `checked ${checked} triangles`);
    assert.deepEqual(mismatches.slice(0, 20), [], `${mismatches.length} mismatches`);
  });

  it("with applyModifiers=0 every triangle lies on its source mesh and carries Blender's nearest polygon", async () => {
    const mismatches = [];
    for (const name of NOAPPLY) {
      const ex = corpus.noapply[name];
      const glb = readGlb(ex.glbPath);
      const meshes = ex.info.annotate.meshes;
      const queries = [];
      const expect = [];
      for (const inst of meshInstances(glb)) {
        trianglesOf(glb, inst).forEach((tri, k) => {
          assert.ok(tri.faceIds, `${name}/${inst.name} has ids`);
          queries.push({ id: `${inst.name}:${k}`, object: inst.name, local: toZup(centroid(tri.localGl)), face: tri.faceIds[0] - 1, mesh: meshes[tri.srcIds[0] - 1].name });
          expect.push({ inst: inst.name, mesh: meshes[tri.srcIds[0] - 1].name, face: tri.faceIds[0] - 1 });
        });
      }
      const answer = await oracle(corpus.blends[name], { points: queries }, corpus.dir);
      answer.points.forEach((a, i) => {
        const e = expect[i];
        if (e.mesh !== answer.objects[e.inst].mesh) mismatches.push(`${name}/${e.inst}: srcId points at ${e.mesh} without modifiers`);
        else if (!(a.bvh_dist < 1e-5) || a.bvh_face !== e.face) mismatches.push(`${name}/${e.inst}: face ${e.face}, Blender nearest ${a.bvh_face} at ${a.bvh_dist}`);
      });
    }
    assert.deepEqual(mismatches.slice(0, 20), []);
  });

  it("a mesh that already has `_dsh_face`/`_dsh_src` attributes is re-tagged with correct ids", () => {
    const glb = glbs.special;
    const meshes = corpus.exports.special.info.annotate.meshes;
    const inst = meshInstances(glb).find((i) => i.name === "PreTagged");
    const tris = trianglesOf(glb, inst);
    assert.deepEqual([...new Set(tris.map((t) => t.faceIds[0]))].sort(), [1, 2, 3, 4, 5, 6]);
    assert.deepEqual([...new Set(tris.map((t) => meshes[t.srcIds[0] - 1]?.name))], ["PreTagged_me"]);
  });

  it("a mesh re-imported from a glTF (upper-case `_DSH_*` POINT attributes) still exports valid srcIds", () => {
    // Re-importing the plugin's own GLB into Blender creates exactly these attributes.
    const glb = glbs.special;
    const meshes = corpus.exports.special.info.annotate.meshes;
    const inst = meshInstances(glb).find((i) => i.name === "Reimported");
    const tris = trianglesOf(glb, inst);
    const srcNames = [...new Set(tris.map((t) => meshes[t.srcIds[0] - 1]?.name ?? `srcId ${t.srcIds[0]} (out of range)`))];
    const faces = [...new Set(tris.map((t) => t.faceIds[0]))].sort((a, b) => a - b);
    assert.deepEqual({ srcNames, faces }, { srcNames: ["Reimported_me"], faces: [1, 2, 3, 4, 5, 6] });
  });

  it("hidden objects are not exported and info.objects[].visible matches Blender's visible_get()", () => {
    const nodes = new Set(meshInstances(glbs.special).map((i) => i.name));
    for (const name of ["HiddenEye", "HiddenMonitor", "HiddenColl"]) assert.ok(!nodes.has(name), `${name} must not be in the GLB`);
    const wrong = corpus.exports.special.info.objects
      .filter((o) => o.type === "MESH")
      .filter((o) => o.visible !== facts.special.objects[o.name].visible)
      .map((o) => `${o.name}: info.visible=${o.visible}, Blender visible_get()=${facts.special.objects[o.name].visible}`);
    assert.deepEqual(wrong, []);
  });

  it("every visible object with geometry appears in the GLB (including geometry-nodes instances)", () => {
    const missing = [];
    for (const name of ["xform", "mods", "bools", "special"]) {
      const nodes = new Set(meshInstances(glbs[name]).map((i) => i.name));
      for (const [obName, ob] of Object.entries(facts[name].objects)) {
        if (!ob.visible || !["MESH", "CURVE", "FONT"].includes(ob.type)) continue;
        if (!nodes.has(obName)) missing.push(`${name}/${obName}`);
      }
    }
    assert.deepEqual(missing, []);
  });

  it("an empty scene exports a valid GLB with an empty annotate block and zero bounds", () => {
    const ex = corpus.exports.empty;
    assert.equal(ex.code, 0);
    assert.deepEqual(ex.info.annotate.meshes, []);
    assert.deepEqual(ex.info.annotate.objects, {});
    assert.deepEqual(ex.info.bounds.size_mm, [0, 0, 0]);
    assert.equal(meshInstances(glbs.empty).length, 0);
  });

  it("multi-scene file: GLB default scene is the active scene and info describes only that scene", () => {
    const ex = corpus.exports.multiscene;
    const glb = glbs.multiscene;
    assert.equal(glb.json.scenes[glb.json.scene ?? 0].name, facts.multiscene.scene);
    assert.deepEqual(meshInstances(glb).map((i) => i.name), ["MainCube"]);
    const listedVisible = ex.info.objects.filter((o) => o.visible).map((o) => o.name);
    assert.deepEqual({ visible: listedVisible, visible_meshes: ex.info.counts.visible_meshes }, { visible: ["MainCube"], visible_meshes: 1 });
  });

  it("geometry beyond MAX_SOURCE_VERTICES is omitted, ids stay in the GLB, smaller meshes keep geometry", () => {
    const ex = corpus.exports.huge;
    const meshes = ex.info.annotate.meshes;
    const big = meshes.find((m) => m.name === "ABig_me");
    const small = meshes.find((m) => m.name === "BSmall_me");
    assert.equal(big.vertices, 400_010);
    assert.equal(big.tagged, true);
    assert.equal(big.geometry, null);
    assert.ok(small.geometry && small.geometry.co.length === 24);
    const inst = meshInstances(glbs.huge).find((i) => i.name === "ABig");
    const tris = trianglesOf(glbs.huge, inst);
    assert.equal(tris.length, 2);
    assert.ok(tris.every((t) => t.faceIds[0] === 1 && meshes[t.srcIds[0] - 1].name === "ABig_me"));
    const r = loadResolver().createResolver(ex.info.annotate, ex.info.unit.millimeters_per_unit).resolve({
      nodeName: "ABig", nodeWorld: inst.world, point: centroid(tris[0].worldGl), normal: [0, 1, 0], faceId: 1, srcId: tris[0].srcIds[0],
    });
    assert.equal(r.face, 0);
    assert.equal(r.mesh, "ABig_me");
    assert.equal(r.precision, "face");
    assert.equal(r.edge, null);
  });

  it("a linked-library mesh is untagged with tag_error, keeps object identity, and resolves at object level", () => {
    const ex = corpus.exports.library;
    const lib = ex.info.annotate.meshes.find((m) => m.name === "LibCube_me");
    assert.equal(lib.tagged, false);
    assert.match(lib.tag_error, /library/);
    assert.ok(ex.info.annotate.objects.LibCube.library.endsWith("libsrc.blend"));
    const inst = meshInstances(glbs.library).find((i) => i.name === "LibCube");
    const tris = trianglesOf(glbs.library, inst);
    assert.equal(tris[0].faceIds, null, "no ids on read-only library data");
    const r = loadResolver().createResolver(ex.info.annotate, 1000).resolve({ nodeName: "LibCube", nodeWorld: inst.world, point: centroid(tris[0].worldGl), faceId: 0, srcId: 0 });
    assert.equal(r.object, "LibCube");
    assert.equal(r.precision, "object");
  });

  it("a local object and a linked object with the same name are both described in annotate.objects", () => {
    const ex = corpus.exports.library;
    const sameName = Object.values(facts.library.objects).filter((o) => o.name === "Shared");
    assert.equal(sameName.length, 2, "Blender has a local and a linked `Shared`");
    const described = Object.values(ex.info.annotate.objects).filter((o) => o.data === "Shared_me");
    assert.deepEqual(
      described.map((o) => (o.library === null ? "local" : "linked")).sort(),
      ["linked", "local"],
      "annotate.objects is keyed by ob.name, so one of the two objects is silently dropped"
    );
  });

  it("annotate.objects transforms, parents, modifier stacks and material slots match Blender", () => {
    for (const name of ["xform", "mods", "bools", "special"]) {
      const objects = corpus.exports[name].info.annotate.objects;
      for (const [obName, truth] of Object.entries(facts[name].objects)) {
        const got = objects[obName];
        assert.ok(got, `${name}/${obName} described`);
        assert.equal(got.type, truth.type, obName);
        assert.equal(got.parent, truth.parent, obName);
        for (let r = 0; r < 4; r += 1) for (let c = 0; c < 4; c += 1) {
          assert.ok(Math.abs(got.matrix_world[r][c] - truth.matrix_world[r][c]) < 1e-6, `${obName} matrix_world[${r}][${c}]`);
        }
        assert.deepEqual(got.material_slots, truth.material_slots, `${obName} material slots`);
      }
    }
    assert.deepEqual(corpus.exports.mods.info.annotate.objects.Bev.modifiers.map((m) => m.type), ["BEVEL"]);
    assert.deepEqual(corpus.exports.bools.info.annotate.objects.BodyDiff.modifiers, [{ name: "Diff", type: "BOOLEAN", show_render: true, object: "CutDiff" }]);
  });

  it("annotate mesh counts match Blender and every MESH object points at its own mesh entry", () => {
    for (const name of ["xform", "mods", "bools", "special", "huge"]) {
      const { meshes, objects } = corpus.exports[name].info.annotate;
      for (const m of meshes) {
        const truth = facts[name].meshes[m.name];
        assert.deepEqual([m.faces, m.edges, m.vertices], [truth.faces, truth.edges, truth.vertices], `${name}/${m.name}`);
        if (m.geometry) {
          assert.equal(m.geometry.co.length, truth.vertices * 3);
          assert.equal(m.geometry.loop_start.length, truth.faces);
          assert.equal(m.geometry.edge_vertices.length, truth.edges * 2);
        }
      }
      for (const [obName, ob] of Object.entries(objects)) {
        if (ob.type !== "MESH") continue;
        assert.equal(meshes[ob.mesh].name, facts[name].objects[obName].mesh, `${name}/${obName}`);
      }
    }
  });
});
